begin;
do $$ begin perform set_config('votus_fiscal_result.workspace_query_owner',pg_has_role(current_user,'workspace_query_owner','SET')::text,true); if not pg_has_role(current_user,'workspace_query_owner','SET') then execute format('grant workspace_query_owner to %I',current_user); end if; end $$;
create view workspace_private.fiscal_party_lookup with(security_barrier=true) as select pm.year,pm.jurisdiction,pm.category,pm.list_id,pm.canonical_party_id,pc.display_name party_name from public.party_mapping pm join public.party_canonical pc on pc.id=pm.canonical_party_id where pm.verified;
create view workspace_private.fiscal_archive_metadata with(security_barrier=true) as select id,sha256,fetched_at,status from public.archive_entry where source_kind='fiscalizacion';
revoke all on workspace_private.fiscal_party_lookup,workspace_private.fiscal_archive_metadata from public,anon,authenticated;
grant select on workspace_private.fiscal_party_lookup,workspace_private.fiscal_archive_metadata to workspace_query_owner;
grant execute on function public.results_exploration_party_jurisdiction(text,integer,text,text,text,text) to workspace_query_owner;
grant create on schema workspace_api to workspace_query_owner;
set role workspace_query_owner;
create function workspace_api.fiscalizacion_result(p_election_id uuid,p_category_id uuid,p_distrito_code text,p_seccion_code text,p_opt_in boolean default false) returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,workspace_private,public,pg_temp as $$
declare auth_status text; scope_allowed boolean; fiscal_total bigint; granularity_total bigint; missing_archive_total bigint; official_excluded_total bigint; row_total bigint; unmapped_total bigint; provenance_total bigint; row_items jsonb; unmapped_items jsonb; provenance_items jsonb; reference jsonb; payload jsonb;
begin
 if not coalesce(p_opt_in,false) then return jsonb_build_object('status','opt_in_required'); end if;
 select min(a.authorization_status),coalesce(bool_or(a.distrito_code=p_distrito_code and a.seccion_code=p_seccion_code),false) into auth_status,scope_allowed from workspace_private.authorized_section_scopes() a;
 if auth_status not in ('authorized','authorized_empty') then return jsonb_build_object('status','authorization_denied','authorization_status',auth_status); end if;
 if not scope_allowed then return jsonb_build_object('status','authorization_denied','authorization_status','scope_denied'); end if;
 select count(*),count(distinct rr.granularity),count(*) filter(where ae.id is null) into fiscal_total,granularity_total,missing_archive_total from public.result_row rr join public.jurisdiction j on j.id=rr.jurisdiction_id left join workspace_private.fiscal_archive_metadata ae on ae.id=rr.archive_entry_id where rr.election_id=p_election_id and rr.category_id=p_category_id and rr.source_kind='fiscalizacion' and j.distrito_code=p_distrito_code and j.seccion_code=p_seccion_code;
 if granularity_total>1 or missing_archive_total>0 then return jsonb_build_object('status','source_inconsistent','exclusions',jsonb_build_object('items',(case when granularity_total>1 then jsonb_build_array(jsonb_build_object('reason','mixed_granularity','rows',fiscal_total)) else '[]'::jsonb end)||(case when missing_archive_total>0 then jsonb_build_array(jsonb_build_object('reason','missing_fiscal_archive_metadata','rows',missing_archive_total)) else '[]'::jsonb end),'total',(granularity_total>1)::integer+(missing_archive_total>0)::integer,'truncated',false)); end if;
 select count(*) into official_excluded_total from public.result_row rr join public.jurisdiction j on j.id=rr.jurisdiction_id where rr.election_id=p_election_id and rr.category_id=p_category_id and rr.source_kind='official' and j.distrito_code=p_distrito_code and j.seccion_code=p_seccion_code;
 select jsonb_build_object('election_year',max(e.year),'election_round',max(e.round),'category_name',max(c.name),'distrito_code',p_distrito_code,'seccion_code',p_seccion_code,'denominator_units',count(distinct rr.jurisdiction_id) filter(where rr.source_kind='official' and rr.granularity='mesa' and j.distrito_code=p_distrito_code and j.seccion_code=p_seccion_code and j.mesa_code is not null)) into reference from public.election e cross join public.category c left join public.result_row rr on rr.election_id=e.id and rr.category_id=c.id left join public.jurisdiction j on j.id=rr.jurisdiction_id and j.distrito_code=p_distrito_code and j.seccion_code=p_seccion_code where e.id=p_election_id and c.id=p_category_id;
 with raw as materialized(select rr.list_id,rr.votes,rr.granularity,rr.archive_entry_id,e.year,c.name category_name,public.results_exploration_party_jurisdiction(rr.archive_entry_id,e.year,e.round,c.name,j.distrito_code,j.seccion_code) mapping_jurisdiction from public.result_row rr join public.jurisdiction j on j.id=rr.jurisdiction_id join public.election e on e.id=rr.election_id join public.category c on c.id=rr.category_id where rr.election_id=p_election_id and rr.category_id=p_category_id and rr.source_kind='fiscalizacion' and j.distrito_code=p_distrito_code and j.seccion_code=p_seccion_code), identified as(select r.*,pm.canonical_party_id,pm.party_name from raw r left join workspace_private.fiscal_party_lookup pm on pm.year=r.year and pm.jurisdiction=r.mapping_jurisdiction and pm.category=r.category_name and pm.list_id=r.list_id), grouped as(select list_id,canonical_party_id,party_name,granularity,count(*) rows,sum(votes)::bigint votes from identified group by list_id,canonical_party_id,party_name,granularity), counted as(select count(*) total from grouped), page as(select * from grouped order by canonical_party_id nulls last,list_id nulls last limit 100) select counted.total,coalesce(jsonb_agg(jsonb_build_object('list_id',page.list_id,'canonical_party_id',page.canonical_party_id,'party_name',page.party_name,'granularity',page.granularity,'votes',page.votes,'rows',page.rows) order by page.canonical_party_id nulls last,page.list_id nulls last) filter(where page.rows is not null),'[]'::jsonb) into row_total,row_items from counted left join page on true group by counted.total;
 with raw as materialized(select rr.list_id,rr.votes,rr.archive_entry_id,e.year,e.round,c.name category_name,j.distrito_code,j.seccion_code from public.result_row rr join public.jurisdiction j on j.id=rr.jurisdiction_id join public.election e on e.id=rr.election_id join public.category c on c.id=rr.category_id where rr.election_id=p_election_id and rr.category_id=p_category_id and rr.source_kind='fiscalizacion' and j.distrito_code=p_distrito_code and j.seccion_code=p_seccion_code), unmapped as(select r.list_id,count(*) rows,sum(r.votes)::bigint votes from raw r left join workspace_private.fiscal_party_lookup pm on pm.year=r.year and pm.jurisdiction=public.results_exploration_party_jurisdiction(r.archive_entry_id,r.year,r.round,r.category_name,r.distrito_code,r.seccion_code) and pm.category=r.category_name and pm.list_id=r.list_id where pm.canonical_party_id is null group by r.list_id), counted as(select count(*) total from unmapped), page as(select * from unmapped order by list_id nulls last limit 100) select counted.total,coalesce(jsonb_agg(jsonb_build_object('list_id',page.list_id,'rows',page.rows,'votes',page.votes) order by page.list_id nulls last) filter(where page.rows is not null),'[]'::jsonb) into unmapped_total,unmapped_items from counted left join page on true group by counted.total;
 with ids as materialized(select distinct rr.archive_entry_id id from public.result_row rr join public.jurisdiction j on j.id=rr.jurisdiction_id where rr.election_id=p_election_id and rr.category_id=p_category_id and rr.source_kind='fiscalizacion' and j.distrito_code=p_distrito_code and j.seccion_code=p_seccion_code), counted as(select count(*) total from ids), page as(select ae.id,ae.sha256,ae.fetched_at,ae.status from ids join workspace_private.fiscal_archive_metadata ae on ae.id=ids.id order by ae.id limit 100) select counted.total,coalesce(jsonb_agg(jsonb_build_object('id',page.id,'sha256',page.sha256,'fetched_at',page.fetched_at,'status',page.status) order by page.id) filter(where page.id is not null),'[]'::jsonb) into provenance_total,provenance_items from counted left join page on true group by counted.total;
 payload:=jsonb_build_object('status',case when fiscal_total=0 then 'no_rows' else 'ok' end,'authorization_status','authorized','source_kind','fiscalizacion','is_random_sample',false,'reference',coalesce(reference,jsonb_build_object('election_year',null,'election_round',null,'category_name',null,'distrito_code',p_distrito_code,'seccion_code',p_seccion_code,'denominator_units',0)),'rows',jsonb_build_object('items',row_items,'total',row_total,'truncated',row_total>100),'unmapped',jsonb_build_object('items',unmapped_items,'total',unmapped_total,'truncated',unmapped_total>100),'exclusions',jsonb_build_object('items',case when official_excluded_total>0 then jsonb_build_array(jsonb_build_object('reason','source_kind_official','rows',official_excluded_total)) else '[]'::jsonb end,'total',case when official_excluded_total>0 then 1 else 0 end,'truncated',false),'provenance',jsonb_build_object('items',provenance_items,'total',provenance_total,'truncated',provenance_total>100),'truncated',row_total>100 or unmapped_total>100 or provenance_total>100);
 if octet_length(payload::text)>120000 then return jsonb_build_object('status','payload_too_large','authorization_status','authorized','source_kind','fiscalizacion','is_random_sample',false,'truncated',true); end if;
 return payload;
end $$;
revoke all on function workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean) from public,anon,authenticated;
grant execute on function workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean) to authenticated;
reset role; revoke create on schema workspace_api from workspace_query_owner;
do $$ begin if to_regrole('service_role') is not null then revoke all on function workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean) from service_role; end if; end $$;
do $$ begin if current_setting('votus_fiscal_result.workspace_query_owner',true)='false' then execute format('revoke workspace_query_owner from %I',current_user); end if; end $$;
commit;
